/**
 * Build a minimal ConTeXt job: user environment preamble + TEXpage around the snippet.
 * No ProjectModel / root / auto \environment injection.
 */
export function buildEquationTexpageSource(environment: string, snippet: string): string {
  const env = environment.trim();
  const body = snippet.trim();
  const parts = [
    '% Generated by ConTeXt Tools equation preview — do not edit.',
    '\\starttext',
  ];
  if (env) {
    parts.push(env);
  }
  parts.push('\\startTEXpage[offset=1ex]', body, '\\stopTEXpage', '\\stoptext', '');
  return parts.join('\n');
}
